INSERT INTO survey_questions SELECT * FROM jsonb_populate_record(NULL::survey_questions, '{"id": "32837f56-ae1a-41c3-88ee-91d2edc7a3b4", "options": null, "category": "structured-survey", "max_pins": null, "required": true, "allow_pin": false, "sub_items": ["Signage is attractive, visible, illuminated, and appropriately located to allow easy navigation throughout campus.", "Exterior building signage is easy to find and easy to read"], "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-07T21:51:42.394522+00:00", "project_id": "X26-RB08", "is_map_based": false, "scale_labels": ["Strongly Agree", "Agree", "Disagree", "Strongly Disagree"], "question_text": "How strongly do you agree or disagree with the statements below about signage on the Baytown Campus?", "question_type": "matrix_likert", "max_selections": null, "question_order": 15}'::jsonb);
