INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "366890c8-9afa-4378-b592-5c782144febf", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-09T19:12:06.912933+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "1fd6c94a-d37b-4cc5-9a3e-7ef2bd7e833f", "response_id": "540708e5-e839-4976-b589-3c5620c926b1", "answer_matrix": {"The campus is attractive and offers an appealing first impression.": "Agree", "The general appearance of the buildings represents the College well.": "Disagree", "Lee College''s campus feels like an active part of the Baytown community": "Agree", "I would use outdoor classrooms and outdoor learning environments if they were available.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
