INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "fd3c8dfa-993f-4094-91e2-9b3b5050c8f9", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-09T20:07:20.336041+00:00", "project_id": "X26-RB08", "answer_text": "Our long history in the Baytown community. Lee College is positioned to be an excellent community resource, if resources, time, and effort were put into improving and modernizing the campus.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "a25e53db-1e95-4ffa-bf53-91666aaa8f76", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "866e14a3-d588-4133-bdcf-de43a4defd93", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-09T20:07:20.409902+00:00", "project_id": "X26-RB08", "answer_text": "My responses are likely quite biased due to the number of years I have spent in my small area inside Bonner Hall. There are numerous areas of improvement around campus, but I have heard directly from students that the visible age of many of our buildings and classrooms disappoints them. Especially those that compare their Lee College experiences to other colleges and universities.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "a25e53db-1e95-4ffa-bf53-91666aaa8f76", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
