INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "b7c3e9bf-39b2-47f7-8f15-d483e4685819", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:13.374641+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "1fd6c94a-d37b-4cc5-9a3e-7ef2bd7e833f", "response_id": "c88df714-4c8b-4d8b-9294-947564904562", "answer_matrix": {"The campus is attractive and offers an appealing first impression.": "Disagree", "The general appearance of the buildings represents the College well.": "Agree", "Lee College''s campus feels like an active part of the Baytown community": "Disagree", "I would use outdoor classrooms and outdoor learning environments if they were available.": "Strongly Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "d9df5a1c-cd53-49c7-9e6d-18b2765c6015", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:13.50954+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "32837f56-ae1a-41c3-88ee-91d2edc7a3b4", "response_id": "c88df714-4c8b-4d8b-9294-947564904562", "answer_matrix": {"Exterior building signage is easy to find and easy to read": "Disagree", "Signage is attractive, visible, illuminated, and appropriately located to allow easy navigation throughout campus.": "Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "e0cab8b8-b426-4a82-a8b9-8aeec472fa15", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:13.659364+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "dbd0ad98-6b33-4cb0-9c73-ea84a379c67b", "response_id": "c88df714-4c8b-4d8b-9294-947564904562", "answer_matrix": {"There are enough parking spaces overall.": "Disagree", "Parking is sufficiently close to where I need to go.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "93b33d32-0eb7-4ae7-a897-b3719120115f", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:13.789902+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "668816cc-de81-431f-86c4-22ccabe16c23", "response_id": "c88df714-4c8b-4d8b-9294-947564904562", "answer_matrix": {"The campus is easy to navigate": "Disagree", "I feel safe walking throughout campus": "Agree", "Buildings are well connected for walking between classes.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "1a9b56fb-9c25-4c4e-945d-198313cc7c3f", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:13.8853+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "e99178ea-e814-49b8-a39c-405164cb9ca0", "response_id": "c88df714-4c8b-4d8b-9294-947564904562", "answer_matrix": {}, "answer_choices": ["Quiet spaces", "Recreation fields or courts"], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, E'{"id": "a69d99e0-2894-47c7-b3f0-60cf26b8f280", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:14.003002+00:00", "project_id": "X26-RB08", "answer_text": "I actually think our campus has a lot of history! A lot of the building are original. Some are so original that they pose a health hazard (haha). However, I would not want to see this history lost in favor of \\"snazzy\\" new buildings. I think keeping our brick and our history intact is important. I also think we have great mature trees, etc. and therefore a fabulous opportunity to create some outdoor spaces worth being in!", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "c88df714-4c8b-4d8b-9294-947564904562", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "35045ec5-4646-46e7-849b-082e259c18b4", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:14.11718+00:00", "project_id": "X26-RB08", "answer_text": "There''s lots of athletic space proportionally (both an old and new gym). And all of the most updated spaces on campus are administrative / student support. We REALLY need to show the primary purpose of the institution (education) some respect and update our academic and learning spaces. It feels kind of disrespectful in some ways that that hasn''t been the priority.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "c88df714-4c8b-4d8b-9294-947564904562", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
