INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "08319852-294c-46c2-9349-11c7b7a05ba1", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:17:38.654351+00:00", "project_id": "X26-RB08", "answer_text": "The friendly and helpful nature of the staff combined with the beauty of the trees and the greenery.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "8336acb3-b073-4c19-99be-8720c926e4b3", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
