INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "8e3bcc18-d07e-454b-bf79-322e000cf5cd", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:18:27.333081+00:00", "project_id": "X26-RB08", "answer_text": "It''s home for most of us. This is where we grew up, and it''s where our grandparents and parents came to school. Additionally, we care about our students and show them that they are more than just a number.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "3d72e598-1668-4d6a-811b-b440187d3cb4", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
