INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "c78187a4-b80a-48d0-b379-437ec20d32b2", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:23:57.427506+00:00", "project_id": "X26-RB08", "answer_text": "We need more spaces that alumni feel welcomed and comfortable to use. Theres so many alumni that when they come they feel like they''re not really supposed to be on campus but its a campus they paid money and got a degree from. They should have a small room on campus so if they''re up here waiting for a sibling or a interview they can come in and not just have to sit outside or in the cafe.", "question_id": "e99178ea-e814-49b8-a39c-405164cb9ca0", "response_id": "964feb22-2151-440c-8826-c04a0cc27af7", "answer_matrix": {}, "answer_choices": ["Other (please specify)"], "answer_ranking": []}'::jsonb);
