INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "93029fca-fdb7-4787-9c8d-b6b6761ff5da", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:39:34.463697+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "1fd6c94a-d37b-4cc5-9a3e-7ef2bd7e833f", "response_id": "1d69495b-ddac-43e5-af7b-8b86d40b45d5", "answer_matrix": {"The campus is attractive and offers an appealing first impression.": "Agree", "The general appearance of the buildings represents the College well.": "Disagree", "Lee College''s campus feels like an active part of the Baytown community": "Agree", "I would use outdoor classrooms and outdoor learning environments if they were available.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "67fcd18c-6531-41ce-9e7a-fa16ea97d156", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:39:34.512541+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "32837f56-ae1a-41c3-88ee-91d2edc7a3b4", "response_id": "1d69495b-ddac-43e5-af7b-8b86d40b45d5", "answer_matrix": {"Exterior building signage is easy to find and easy to read": "Disagree", "Signage is attractive, visible, illuminated, and appropriately located to allow easy navigation throughout campus.": "Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "d5f27a0c-e0d0-4669-b19b-a81343e459b7", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:39:34.565241+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "dbd0ad98-6b33-4cb0-9c73-ea84a379c67b", "response_id": "1d69495b-ddac-43e5-af7b-8b86d40b45d5", "answer_matrix": {"There are enough parking spaces overall.": "Disagree", "Parking is sufficiently close to where I need to go.": "Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "4fcb1b7d-c8c2-44ac-b469-4ecf7f2f538b", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:39:34.615706+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "668816cc-de81-431f-86c4-22ccabe16c23", "response_id": "1d69495b-ddac-43e5-af7b-8b86d40b45d5", "answer_matrix": {"The campus is easy to navigate": "Disagree", "I feel safe walking throughout campus": "Agree", "Buildings are well connected for walking between classes.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "88379f94-d548-4c80-9288-93185089bbcd", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:39:34.669883+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "e99178ea-e814-49b8-a39c-405164cb9ca0", "response_id": "1d69495b-ddac-43e5-af7b-8b86d40b45d5", "answer_matrix": {}, "answer_choices": ["Indoor recreation facilities", "Recreation fields or courts"], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, E'{"id": "f2314c44-f16a-4f68-8f98-72f9789bc2ae", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:39:34.720282+00:00", "project_id": "X26-RB08", "answer_text": "It feels like a community, not a college.\\nStudents don’t get lost in the crowd.\\nFaculty and staff actually know students by name, check on them, and help them navigate life — not just classes.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "1d69495b-ddac-43e5-af7b-8b86d40b45d5", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, E'{"id": "a009d0f1-654d-4aa9-aa31-bfed08988188", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T13:39:34.767519+00:00", "project_id": "X26-RB08", "answer_text": "Strengthening the student‑centered culture\\nThe campus already has a reputation for being personal, supportive, and community‑driven. Protecting and expanding that culture should remain a priority. Students thrive when they feel seen, supported, and connected and Baytown does that well.\\nSome buildings and learning spaces would benefit from updated technology, refreshed interiors, and more flexible classroom layouts. Modern spaces help students feel like they’re learning in an environment that matches the quality of instruction.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "1d69495b-ddac-43e5-af7b-8b86d40b45d5", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
