INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "4cdce7a5-98cb-4826-8cdc-7fbe51fc4911", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:01:07.043653+00:00", "project_id": "X26-RB08", "answer_text": "Lots of history, and passion.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "247d61fc-97e6-4e70-ab23-d2838bc68f7a", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "5f27295d-fdb1-4f1c-b47d-9bb4f07bbb73", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:01:07.095209+00:00", "project_id": "X26-RB08", "answer_text": "I personally would like to see the use of Texas Ave buildings being used as Live Labs. An opportunity to bring Open to Public access, and revitalize downtown district, while offering a way to bring funds in for student workers, and other parts of the college. Business, Arts, Music, Culinary, Logistics, etc. could all benefit from this. It would teach real world experiences, teamwork, and soft skills, in a fun way - plus it helps revitalize our city - and it is next door! Endless opportunity, plus it could be grant funded. Something I have thought about for a long time!", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "247d61fc-97e6-4e70-ab23-d2838bc68f7a", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
