INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "21d934a4-57a7-4a28-93ea-6b240a13d08e", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:06:21.560706+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "32837f56-ae1a-41c3-88ee-91d2edc7a3b4", "response_id": "d376bf90-c0d0-4b1e-aba9-d89a91144c2d", "answer_matrix": {"Exterior building signage is easy to find and easy to read": "Disagree", "Signage is attractive, visible, illuminated, and appropriately located to allow easy navigation throughout campus.": "Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "877acf94-f5d6-4f5c-845b-db41252f9718", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:06:21.613872+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "dbd0ad98-6b33-4cb0-9c73-ea84a379c67b", "response_id": "d376bf90-c0d0-4b1e-aba9-d89a91144c2d", "answer_matrix": {"There are enough parking spaces overall.": "Agree", "Parking is sufficiently close to where I need to go.": "Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "ca4c1c18-3642-4383-8800-f7700be249fc", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:06:21.667691+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "668816cc-de81-431f-86c4-22ccabe16c23", "response_id": "d376bf90-c0d0-4b1e-aba9-d89a91144c2d", "answer_matrix": {"The campus is easy to navigate": "Agree", "I feel safe walking throughout campus": "Agree", "Buildings are well connected for walking between classes.": "Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, E'{"id": "c044be7b-d6cb-4d0c-8eb8-0329d0122fb8", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:06:21.719174+00:00", "project_id": "X26-RB08", "answer_text": "Campus eating areas that extend beyond the café and include outdoor spaces as well as indoor areas equipped with microwaves for student use. \\nIn addition, some rooftop event/recreation/study areas might be nice for us to use spaces that are not traditionally used.", "question_id": "e99178ea-e814-49b8-a39c-405164cb9ca0", "response_id": "d376bf90-c0d0-4b1e-aba9-d89a91144c2d", "answer_matrix": {}, "answer_choices": ["Indoor recreation facilities", "Other (please specify)"], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "326315b8-f9fb-413b-b1e4-cb3379f356c5", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:06:21.774787+00:00", "project_id": "X26-RB08", "answer_text": "Main Campus is located in the part of Baytown where there is a need to expand financial opportunities for its residents. People are aware that it''s there, but there is an opportunity to become better connected to that community so residents can actually see the benefit of participating in our programs.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "d376bf90-c0d0-4b1e-aba9-d89a91144c2d", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, E'{"id": "7b613afa-3a98-42b4-868e-b7ff98af245e", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:06:21.832346+00:00", "project_id": "X26-RB08", "answer_text": "Exits from the lots along Lee Drive present safety concerns, particularly the exit between Lots 1 and 2, where overgrown bushes restrict visibility when turning onto Lee Drive. Some solutions include trimming or removing the bushes, installing a four-way stop, or closing that exit entirely.\\nCovered walkways would also be a valuable addition to the campus. \\nA pedestrian bridge/walkway across the field between the ATC and PAC would increase safety by eliminating the need to use the sidewalk along Lee Dr. and by reducing the time it takes to reach the PAC for those in buildings beyond the ATC.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "d376bf90-c0d0-4b1e-aba9-d89a91144c2d", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
