INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "243d909f-9a5a-41d4-affc-b5445e388629", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:06:47.153541+00:00", "project_id": "X26-RB08", "answer_text": "I like the outdoor atmosphere of the campus between buildings", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "ff130f34-bbd2-4855-97c5-1c7c01d7e236", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "4f8b0c3c-c8f7-48cf-a4a0-d97be208f15d", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:06:47.208632+00:00", "project_id": "X26-RB08", "answer_text": "Id really just like to point out Huddle once more, and the half-done asbestos abatement. This building is attached right to our main admin building, but is in complete disarray. Our largest main conference hall in Rundell is directly attached to a building with no walls, flooring, electrical, and is packed full with surplus furniture. This is not a prideful building and im not sure why its been sitting like that for so long, it is a bad look for the college. Imagine how bad it must look to our outside community members.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "ff130f34-bbd2-4855-97c5-1c7c01d7e236", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
