INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "9aacaa12-d8b8-4f66-91d3-1e5ea0f11db9", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:18.219087+00:00", "project_id": "X26-RB08", "answer_text": "A state of the art performing arts center that any  artist, local, nationally or internationally known, would love to perform in, that can attract the masses from the Houston area and beyond and can elevate the entire campus'' vision and presence within the community. Making our campus more appealing to students around us.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "52d281e9-9ac7-451f-bd30-e78c005fc6c3", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:18.27613+00:00", "project_id": "X26-RB08", "answer_text": "The more we work together, the more we can get done.  The performing arts center needs more departments and people involved that believe in the success of what that space can do for us all.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
