INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "822e456e-a791-431d-8c50-43cbcaf9f44a", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:29:24.656208+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "1fd6c94a-d37b-4cc5-9a3e-7ef2bd7e833f", "response_id": "f0451226-1c3d-4b6b-8a76-7db35f61d938", "answer_matrix": {"The campus is attractive and offers an appealing first impression.": "Disagree", "The general appearance of the buildings represents the College well.": "Agree", "Lee College''s campus feels like an active part of the Baytown community": "Disagree", "I would use outdoor classrooms and outdoor learning environments if they were available.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "3fac57eb-829c-48de-959e-0aca5466d71e", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:29:24.719063+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "32837f56-ae1a-41c3-88ee-91d2edc7a3b4", "response_id": "f0451226-1c3d-4b6b-8a76-7db35f61d938", "answer_matrix": {"Exterior building signage is easy to find and easy to read": "Strongly Disagree", "Signage is attractive, visible, illuminated, and appropriately located to allow easy navigation throughout campus.": "Strongly Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "d0e48642-ab9d-4879-9e02-09ff30bd1df1", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:29:24.776319+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "dbd0ad98-6b33-4cb0-9c73-ea84a379c67b", "response_id": "f0451226-1c3d-4b6b-8a76-7db35f61d938", "answer_matrix": {"There are enough parking spaces overall.": "Disagree", "Parking is sufficiently close to where I need to go.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
