INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "4d98bade-8e7f-447a-b3a0-b55a05c5e04b", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:58:19.507228+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "32837f56-ae1a-41c3-88ee-91d2edc7a3b4", "response_id": "dade0367-7ae1-41cf-9acb-d6c36340ccd9", "answer_matrix": {"Exterior building signage is easy to find and easy to read": "Agree", "Signage is attractive, visible, illuminated, and appropriately located to allow easy navigation throughout campus.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
