INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "b4869d10-4a55-469a-b255-42740eeea751", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:58:19.659501+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "e99178ea-e814-49b8-a39c-405164cb9ca0", "response_id": "dade0367-7ae1-41cf-9acb-d6c36340ccd9", "answer_matrix": {}, "answer_choices": ["Indoor recreation facilities"], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "90acac08-fef7-4490-bff5-8f8b8980134e", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:58:19.709993+00:00", "project_id": "X26-RB08", "answer_text": "With five consolidated ISDs serving the area, Baytown is a community rooted in Educational Execellence. As a Junior College located directly within community, Lee College offers more than just Academic programs; it provides tranformation where generations of families have begun their professional journeys.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "dade0367-7ae1-41cf-9acb-d6c36340ccd9", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "78861491-4603-40ad-a764-60b781e5ea3b", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:58:19.766675+00:00", "project_id": "X26-RB08", "answer_text": "I am grateful for the opportunities Lee College has provide my family over the years. With two generations of our family having already attended, and a third soon to follow. Lee College continues to support both its students and the Baytown community.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "dade0367-7ae1-41cf-9acb-d6c36340ccd9", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
