INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "99963560-c7d6-4fdd-9694-7a8f0967ad80", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:54.369694+00:00", "project_id": "X26-RB08", "answer_text": "As the flagship campus upon moving away from using GCCISD facilities, the history/heritage of the Baytown Campus is something we should lean into.  While infrastructure updates are paramount to having a safe and functional campus now and in the future, the fact that this campus has existed since the 1950''s should at least be considered as changes are made.  With that said, there are opportunities for expansion/growth in other parts of the community that I think would serve distant portions of our service area more effectively.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
