INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "feb2579d-54a6-45f0-98b7-4782aa2f9483", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:34:24.600127+00:00", "project_id": "X26-RB08", "answer_text": "It is a central piece in Baytown''s identity", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "0b972ed3-b7d9-4454-9283-22371f90ead0", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "3e92d973-954d-448c-97f1-44966498f4c3", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:34:24.655372+00:00", "project_id": "X26-RB08", "answer_text": "The grounds and buildings need much better care than they''re getting. Trash is often left on the lawns and frequently mowed over. Moler Hall looks great, but John Britt Hall, while it''s had some upgrades, still doesn''t get star treatment. Painting is sloppy, upkeep seems limited to emptying trash, and a lot of the walls and floors look like what they are ... a half-hearted attempt to cover over old, worn surfaces. Hot water isn''t available everywhere, and appliances don''t do all that they should (ice in the refrigerator would be nice, for example). The men''s room in Marketing doesn''t seem to ever be mopped well, and a large amount of adhesive backing/residue has been stuck on the window ledge for years. An awning over the back/side entrance to Britt has been in tatters for more than a decade. It really seems as though no one cares.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "0b972ed3-b7d9-4454-9283-22371f90ead0", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
