INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "86cb3c2a-7b4c-423f-8236-b4defa358491", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:09:05.027401+00:00", "project_id": "X26-RB08", "answer_text": "Located downtown Baytown and it needs a huge upgrade, it''s old and busted looking the outer perimeter of the campus is semi decent but once you get start walking on campus and into some buildings its disgusting.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "c5eac9e5-90cf-4990-8e08-65801022ded6", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "8486006a-2161-4530-b0f4-7e47a6989b09", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:09:05.078552+00:00", "project_id": "X26-RB08", "answer_text": "Baytown campus needs a huge renovation, new buildings, new landscaping, just a modern overhall would make a huge difference.  I hear students say out campus is ugly and outdated and in poor conditions.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "c5eac9e5-90cf-4990-8e08-65801022ded6", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
