INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "5651e471-fd4f-4bf6-adc5-a79acdacb25f", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:32:49.466685+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "e99178ea-e814-49b8-a39c-405164cb9ca0", "response_id": "c8bd7e90-a20a-439f-b888-758a8923c5d6", "answer_matrix": {}, "answer_choices": ["Quiet spaces", "Indoor recreation facilities"], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "b7f30b03-a9f9-4f2b-80e2-981eb1338096", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:32:49.514999+00:00", "project_id": "X26-RB08", "answer_text": "It''s the people, moreso than the facilities.  This always will be the case, but that''s not to say there isn''t room for facility improvements.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "c8bd7e90-a20a-439f-b888-758a8923c5d6", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "595af984-584a-4796-9f6b-bf5a14327eb7", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:32:49.57182+00:00", "project_id": "X26-RB08", "answer_text": "Modification of Gulf Street years ago to essentially discontinue its use as a public thoroughfare was a good thing.  Any similar step that can be discussed/considered with City of Baytown - to involve even Texas Avenue north of McNulty-Haddick - would be worth introducing.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "c8bd7e90-a20a-439f-b888-758a8923c5d6", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
