INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "55498b19-2996-4d1b-83d3-251852cabed1", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:40.97407+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "6d31ae57-7fb9-4853-9af3-8a88be0314ff", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, E'{"id": "a450b4df-790f-4af7-a170-99a3abcb6404", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:41.118103+00:00", "project_id": "X26-RB08", "answer_text": "None of these options REALLY support students or the community. \\n\\nThe best service we could offer the community is to not lower our standards any more than we already have. \\n\\nI should not have to write instructions below a 6th grade reading level and offer them as bullet points. These students are NOT college ready, and we are graduating supremely unprepared students. There is no way to bring a 6th grader up to the level of a college freshman in less than 30 class meetings.", "question_id": "10010a74-a82f-4bc1-9dc6-4b321696dc2a", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3", "answer_matrix": {}, "answer_choices": ["Other"], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "549a426d-fcbe-4960-a4d6-16eb9b091c4d", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:41.242073+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "1fd6c94a-d37b-4cc5-9a3e-7ef2bd7e833f", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3", "answer_matrix": {"The campus is attractive and offers an appealing first impression.": "Strongly Disagree", "The general appearance of the buildings represents the College well.": "Strongly Disagree", "Lee College''s campus feels like an active part of the Baytown community": "Strongly Disagree", "I would use outdoor classrooms and outdoor learning environments if they were available.": "Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "1cb34fbd-505c-468d-b148-8711019cb59e", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:41.315682+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "32837f56-ae1a-41c3-88ee-91d2edc7a3b4", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3", "answer_matrix": {"Exterior building signage is easy to find and easy to read": "Strongly Disagree", "Signage is attractive, visible, illuminated, and appropriately located to allow easy navigation throughout campus.": "Strongly Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "60703508-c2b4-401d-9c4f-50a50ca0bd9b", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:41.384733+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "dbd0ad98-6b33-4cb0-9c73-ea84a379c67b", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3", "answer_matrix": {"There are enough parking spaces overall.": "Agree", "Parking is sufficiently close to where I need to go.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
