INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "9fcb0c7b-bc7d-4e64-ae24-ac8568acc398", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:41.520266+00:00", "project_id": "X26-RB08", "answer_text": "I picked this only because I had to pick two.", "question_id": "e99178ea-e814-49b8-a39c-405164cb9ca0", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3", "answer_matrix": {}, "answer_choices": ["Quiet spaces", "Other (please specify)"], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, E'{"id": "f225e597-0ffc-4927-8e55-2f45cd0fb253", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:41.592402+00:00", "project_id": "X26-RB08", "answer_text": "\\"Special\\" how? In the purest English language sense or in the Dana Carvey Church Lady SNL skit way?\\n\\nI can''t answer the first version. It''s special because it''s where I make the money I need to live my actual life.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, E'{"id": "403f58f2-c657-47e3-ab75-41528320ab3e", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:41.665648+00:00", "project_id": "X26-RB08", "answer_text": "Security needs to be much MUCH more visible, especially at night. I walked alone across campus after dark two nights a week. I saw security one time, and he managed to scare me.\\n\\nSomeone needs to inspect the crap job that''s being done inside buildings. They''re doing a somewhat decent job with the most public parts, but heaven forbid a student actually enter an office and look around. The work done in my office is embarrassing.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
