INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "e2eacdc5-c7d7-4bf8-b424-d8233b205d54", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T21:13:21.13568+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "1fd6c94a-d37b-4cc5-9a3e-7ef2bd7e833f", "response_id": "f90469e2-f47b-4225-b7ab-ade3996774bd", "answer_matrix": {"The campus is attractive and offers an appealing first impression.": "Agree", "The general appearance of the buildings represents the College well.": "Disagree", "Lee College''s campus feels like an active part of the Baytown community": "Agree", "I would use outdoor classrooms and outdoor learning environments if they were available.": "Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
