INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "3cb3302d-e0bc-4c9d-af38-d8f083ed3108", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T21:16:24.982914+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "e99178ea-e814-49b8-a39c-405164cb9ca0", "response_id": "14c2ee73-48a1-4e2f-85f1-1581b0ab9865", "answer_matrix": {}, "answer_choices": ["Indoor recreation facilities"], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "f0671afd-2acc-494b-a0a1-449b5641b024", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T21:16:25.033068+00:00", "project_id": "X26-RB08", "answer_text": "I love the large trees and all the green grass that is part of the Baytown campus. There are a lot of things that are visually appealing, but some things that need work (the sidewalks behind JBH and the signage on the Felton st. side of the nursing building).", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "14c2ee73-48a1-4e2f-85f1-1581b0ab9865", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "b6bfde30-1bc1-42e6-b77d-084e9488b728", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T21:16:25.089515+00:00", "project_id": "X26-RB08", "answer_text": "It would be nice to have some kind of barrier between the surrounding neighborhoods and the college with specific entrances -- not completely open on all sides.", "question_id": "16d84780-9ad7-439a-bbe3-d3d80e862464", "response_id": "14c2ee73-48a1-4e2f-85f1-1581b0ab9865", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
