INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "cba1bd3b-5817-45a8-8457-1a94f07d97cd", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-12T05:12:44.360524+00:00", "project_id": "X26-RB08", "answer_text": "I love how everything is connected!! There are many ways to go to a single place.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "b9c6388d-7a25-4d36-99a1-da1dd86578dc", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
