INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "9ccf8ed1-e970-457e-9741-231250aaf8c6", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-12T16:18:44.841835+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "1fd6c94a-d37b-4cc5-9a3e-7ef2bd7e833f", "response_id": "94ef574c-677f-4e65-8cab-0f40492aa4cf", "answer_matrix": {"The campus is attractive and offers an appealing first impression.": "Disagree", "The general appearance of the buildings represents the College well.": "Disagree", "Lee College''s campus feels like an active part of the Baytown community": "Disagree", "I would use outdoor classrooms and outdoor learning environments if they were available.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "5db0b238-21c3-41b8-8590-7866a41d602b", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-12T16:18:44.91276+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "32837f56-ae1a-41c3-88ee-91d2edc7a3b4", "response_id": "94ef574c-677f-4e65-8cab-0f40492aa4cf", "answer_matrix": {"Exterior building signage is easy to find and easy to read": "Disagree", "Signage is attractive, visible, illuminated, and appropriately located to allow easy navigation throughout campus.": "Disagree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "e6f2a05e-7858-46fc-a18b-68188e82d586", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-12T16:18:44.976263+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "dbd0ad98-6b33-4cb0-9c73-ea84a379c67b", "response_id": "94ef574c-677f-4e65-8cab-0f40492aa4cf", "answer_matrix": {"There are enough parking spaces overall.": "Agree", "Parking is sufficiently close to where I need to go.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "ac6e91dd-5ad9-448d-b6c0-23727e020c17", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-12T16:18:45.047214+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "668816cc-de81-431f-86c4-22ccabe16c23", "response_id": "94ef574c-677f-4e65-8cab-0f40492aa4cf", "answer_matrix": {"The campus is easy to navigate": "Agree", "I feel safe walking throughout campus": "Agree", "Buildings are well connected for walking between classes.": "Agree"}, "answer_choices": [], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "2f4b63d0-022d-4cba-8854-2bb238421029", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-12T16:18:45.115391+00:00", "project_id": "X26-RB08", "answer_text": null, "question_id": "e99178ea-e814-49b8-a39c-405164cb9ca0", "response_id": "94ef574c-677f-4e65-8cab-0f40492aa4cf", "answer_matrix": {}, "answer_choices": ["Quiet spaces"], "answer_ranking": []}'::jsonb);
INSERT INTO survey_answers SELECT * FROM jsonb_populate_record(NULL::survey_answers, '{"id": "8ae1dcec-023b-4882-b75f-4337156e0a29", "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-12T16:18:45.20524+00:00", "project_id": "X26-RB08", "answer_text": "The people make the difference in making the campus feel welcoming.", "question_id": "8b9ba8ea-5752-43d8-bf5f-cb8a71786cfa", "response_id": "94ef574c-677f-4e65-8cab-0f40492aa4cf", "answer_matrix": {}, "answer_choices": [], "answer_ranking": []}'::jsonb);
