INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "b25401ae-453b-4792-95d2-5600360f5b05", "note": "I like that we have a fountain!", "latitude": 29.7322207799274, "answer_id": "d6dec044-b43a-4b45-90d9-1b1ff234e9fd", "longitude": -94.9776539497372, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:10.381363+00:00", "project_id": "X26-RB08", "question_id": "63092fe4-0cba-4184-9f51-2b3e22f86ace", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "ee54ec7c-ddc3-4868-a24b-884b401bccfe", "note": "I think the inside of the Arena is very nice.", "latitude": 29.731065537901, "answer_id": "d6dec044-b43a-4b45-90d9-1b1ff234e9fd", "longitude": -94.9780187301632, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:10.381363+00:00", "project_id": "X26-RB08", "question_id": "63092fe4-0cba-4184-9f51-2b3e22f86ace", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "7d57faa1-7bec-4b7a-8091-c5a670efaa8d", "note": "Love a good walkable grassy area. I like our gazebo and the sitting area in front of Moler. I love outdoor plazas / seating on university campuses.", "latitude": 29.7319040213407, "answer_id": "b07f5df1-c54d-4ea9-a214-f25419ee17e5", "longitude": -94.9761626415247, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:10.721157+00:00", "project_id": "X26-RB08", "question_id": "8ed522d7-927b-4289-bae2-ccdf78beda1b", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "780e3b02-1bd6-4d6a-ae98-4195c54056a9", "note": "There is one sort of random picnic table area here that I like. Again, I think because it is one of the only outdoor seating areas. It feels organic, well surrounded by academic buildings. There''s so few spaces to sit that aren''t classrooms or study spaces on campus.", "latitude": 29.7311959691188, "answer_id": "b07f5df1-c54d-4ea9-a214-f25419ee17e5", "longitude": -94.9766883544919, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:10.721157+00:00", "project_id": "X26-RB08", "question_id": "8ed522d7-927b-4289-bae2-ccdf78beda1b", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "15f9fb8f-6816-4afc-80d9-fe5c95338719", "note": "This building is a death-trap (mold, air quality, failing facilities). That they still have people working in there is wild to me.", "latitude": 29.7313264001661, "answer_id": "97531e71-5b26-454c-a7b3-16befa2b859f", "longitude": -94.976001708984, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:11.341728+00:00", "project_id": "X26-RB08", "question_id": "b910be74-0cc8-49ca-a30b-60eeb06b04ed", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "a3938575-10ad-4c5d-afbf-057b9f9934ae", "note": "Again: mold, collapsing floors, asbestos. What are we doing, people?", "latitude": 29.7315779452801, "answer_id": "97531e71-5b26-454c-a7b3-16befa2b859f", "longitude": -94.9768922023767, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:11.341728+00:00", "project_id": "X26-RB08", "question_id": "b910be74-0cc8-49ca-a30b-60eeb06b04ed", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "5ec48a30-18eb-47d3-80f5-f3bee25e2c2f", "note": "Please see my overall note.", "latitude": 29.7330778863829, "answer_id": "f5fb2083-a6c0-4763-aab0-26d231806547", "longitude": -94.97819039154, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:11.791971+00:00", "project_id": "X26-RB08", "question_id": "a2f5e139-1ea9-4cc6-9862-6a12a237164c", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
