INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "3b7e4055-0b73-4486-b298-17e241b062b7", "note": "My office and one of the rooms in this building are common meeting sites for me. I have a good size office conducive to having multiple people in it at once.", "latitude": 29.732369842446, "answer_id": "2ba534af-a0dc-4226-874c-1fc5b1dab1b6", "longitude": -94.9771818809507, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:12.528575+00:00", "project_id": "X26-RB08", "question_id": "cd40af26-184e-4ccb-8525-1276f99c7481", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "ef75fcbc-f052-4284-b3a6-e5728a0a4f24", "note": "This is where we have faculty assembly its a nice facility since the renovations. Though I felt like before the renovations it certainly wasn''t the place on campus with the most need. But I suppose the board always seems to come first.", "latitude": 29.732667966818, "answer_id": "2ba534af-a0dc-4226-874c-1fc5b1dab1b6", "longitude": -94.9762699298857, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:12.528575+00:00", "project_id": "X26-RB08", "question_id": "cd40af26-184e-4ccb-8525-1276f99c7481", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "0389189e-ade3-492a-896c-851b6098a393", "note": "I eat in my office. Food brought from home. Not ideal. But the food options on campus do not satisfy and there is not enough seating around on campus for both faculty and staff and students to all make use.", "latitude": 29.7323418932405, "answer_id": "3ec55a19-c83a-4f6b-abf0-46b19fb99efd", "longitude": -94.977278440475, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-04-11T00:47:12.928412+00:00", "project_id": "X26-RB08", "question_id": "b91b3d5f-6b39-4885-83db-d6c548031744", "response_id": "c88df714-4c8b-4d8b-9294-947564904562"}'::jsonb);
