INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "d27d836c-7cfc-4d86-a460-f3615ef4f7a8", "note": "Entertainment capital of Baytown, The Performing Arts Center.", "latitude": 29.7344461341541, "answer_id": "ea6a4af5-f182-4eb6-a7c2-7c190ffc476b", "longitude": -94.9770034650021, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:16.872692+00:00", "project_id": "X26-RB08", "question_id": "adc4763b-f468-4810-a023-79c50e99b97f", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "65a577e4-538c-4b9e-a885-f0a79deb6ed2", "note": "Start of the art facility with plenty of natural light, great landscape and even more potential with areas to add more landscaping, parking, outdoor art and outdoor events. We also offer ideal spaces on the inside for photo ops.", "latitude": 29.7344978696556, "answer_id": "6f2bf7db-1bef-4090-9d46-aef750e1b936", "longitude": -94.976955800813, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:16.990733+00:00", "project_id": "X26-RB08", "question_id": "63092fe4-0cba-4184-9f51-2b3e22f86ace", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "faeed97b-c9a6-4d5f-bf79-0d0eb81faf1d", "note": "The open and hilly lawn at the PAC.", "latitude": 29.733980513441, "answer_id": "bb77fa24-9e01-4266-a652-2f049646c212", "longitude": -94.9773013661853, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:17.107504+00:00", "project_id": "X26-RB08", "question_id": "8ed522d7-927b-4289-bae2-ccdf78beda1b", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "09788d57-3844-442a-afe2-b3e64c481496", "note": "We can do so much more together. We should be a landmark  of entertainment for not just Baytown but the greater Baytown area and Houston.", "latitude": 29.7344875225567, "answer_id": "f7211a5b-471d-4c1f-a2a1-b2ff15ca2de6", "longitude": -94.9771107094279, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:17.223557+00:00", "project_id": "X26-RB08", "question_id": "b910be74-0cc8-49ca-a30b-60eeb06b04ed", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "1fbaffe7-3a35-4752-b411-8a1441fcbf67", "note": "I feel safe on this campus, for the most part, but I know we must always be aware of anyone coming from the main roads off or adjacent from campus.", "latitude": 29.7300071287785, "answer_id": "6e2e5f11-2a42-4412-8320-c8303d68269e", "longitude": -94.9779090845989, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:17.328996+00:00", "project_id": "X26-RB08", "question_id": "a2f5e139-1ea9-4cc6-9862-6a12a237164c", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "a4b76ea8-7a21-45cc-b26a-134b06e80cbe", "note": "Carpet in the Main Hall, updated aesthetics, bathrooms with showers that are accessible for the talent to use, upgraded equipment to support the event we want to showcase at the PAC.", "latitude": 29.7344254399455, "answer_id": "b27390d6-f34d-4695-9d44-fef118ad4a50", "longitude": -94.9770868773336, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:17.448444+00:00", "project_id": "X26-RB08", "question_id": "8f13babc-586d-4acc-abb7-c1a0fd13a379", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "8794808d-1b01-4eb9-8867-15f859ae1b0a", "note": "The lobby, green room, Art Gallery, or conference space are great options to meet casually or with more privacy.", "latitude": 29.7345702992993, "answer_id": "ccb73d10-87be-48c7-b99a-9f5400d97f0e", "longitude": -94.9771107094273, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:17.572032+00:00", "project_id": "X26-RB08", "question_id": "cd40af26-184e-4ccb-8525-1276f99c7481", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "7b504d27-7c4b-4057-b923-e7852b9e5b32", "note": "I love to eat here when there are campus events.", "latitude": 29.7320041881231, "answer_id": "6ab79fd4-35d3-4008-aaca-2f48beb98b73", "longitude": -94.9760501812151, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T14:28:17.686878+00:00", "project_id": "X26-RB08", "question_id": "b91b3d5f-6b39-4885-83db-d6c548031744", "response_id": "430d45d1-272f-4712-a1db-908bdbd1d0f9"}'::jsonb);
