INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "a940d26c-6b2e-4709-a74b-fdec9a0a672d", "note": "If I can only choose one location it would be the Student Center.  This space serves as a gathering location for students to engage in extracurricular activities.  while other locations are important on this front, the Gym and the library spring to mind, the Student Center seems like a hub for both beginning and continuing students on a day-to-day basis.  Now, if we''re talking about getting students into the institution initially, that would be Rundell Hall.", "latitude": 29.7323543149203, "answer_id": "48987b99-52eb-44a2-ab95-495ce0d03fd7", "longitude": -94.9760553531639, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.146906+00:00", "project_id": "X26-RB08", "question_id": "adc4763b-f468-4810-a023-79c50e99b97f", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "b0439e5a-9b07-411c-8753-2446d9e5f983", "note": "There are some flower bed benches that provide a nice seating area and decent foliage back drops for photos around the Lee College Mall.", "latitude": 29.7313574549627, "answer_id": "1884614a-6268-4ebd-8b65-9627a10a9f21", "longitude": -94.9773428134909, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.273049+00:00", "project_id": "X26-RB08", "question_id": "63092fe4-0cba-4184-9f51-2b3e22f86ace", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "361e94b3-9c21-4ea9-a8ae-c49e47db6c85", "note": "Not particularly LC centric, but there are some really old and well-shaped trees in this spot for photos.", "latitude": 29.7333604812808, "answer_id": "1884614a-6268-4ebd-8b65-9627a10a9f21", "longitude": -94.9752936058036, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.273049+00:00", "project_id": "X26-RB08", "question_id": "63092fe4-0cba-4184-9f51-2b3e22f86ace", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "3293b3c2-cac2-41f3-abfd-1ec088f449df", "note": "The gazebo provides a good location for being outdoors without being too exposed to the elements.", "latitude": 29.7316648988095, "answer_id": "c8b3e53e-d58b-4cb0-8a04-301d435aec0c", "longitude": -94.9763128452293, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.379855+00:00", "project_id": "X26-RB08", "question_id": "8ed522d7-927b-4289-bae2-ccdf78beda1b", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "feb2b5ae-9b70-403b-b47f-590be089be84", "note": "I think if people think of it as the quad, this area can/could be a really nice place to relax outdoors.  I see people sitting on the benches around the fountain sporadically.", "latitude": 29.732167986709, "answer_id": "c8b3e53e-d58b-4cb0-8a04-301d435aec0c", "longitude": -94.9776217632284, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.379855+00:00", "project_id": "X26-RB08", "question_id": "8ed522d7-927b-4289-bae2-ccdf78beda1b", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "2f2d6880-ad92-4639-8578-e35b98ed4d57", "note": "Moler Hall strikes me as wasted potential based on being a one-story building at the heart of campus.  It seems to have infrastructure issues that I think would be concerning.  A new build on this site could provide office space and multiuse space in a centralized location on the main campus that could alleviate some concerns that pop up periodically.", "latitude": 29.7315903670543, "answer_id": "ee6b8628-78b8-41fc-b36d-6de90f0d32fd", "longitude": -94.9767741851796, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.488803+00:00", "project_id": "X26-RB08", "question_id": "b910be74-0cc8-49ca-a30b-60eeb06b04ed", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "63cbc57c-5a0f-489a-ba7c-94a82451cd8d", "note": "Huddle Building seems like wasted potential and needs a significant remodel to be usable beyond the few office spaces and one classroom that are there.", "latitude": 29.7322332016225, "answer_id": "ee6b8628-78b8-41fc-b36d-6de90f0d32fd", "longitude": -94.9782225780476, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.488803+00:00", "project_id": "X26-RB08", "question_id": "b910be74-0cc8-49ca-a30b-60eeb06b04ed", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "f7fc613f-9a9e-4ace-8a34-282cc00d065d", "note": "When exiting the parking lot from this driveway it is a blind spot for any low vehicles.", "latitude": 29.7327549194028, "answer_id": "dadfc49c-2ef3-444f-9354-aa1ae4cfcdf6", "longitude": -94.9789306812279, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.590865+00:00", "project_id": "X26-RB08", "question_id": "a2f5e139-1ea9-4cc6-9862-6a12a237164c", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
