INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "cbcc5811-2d4a-4dcd-b91d-b546fc60ab97", "note": "This block of TV Buildings need improvement if classes are to be taught there or they need to be repurposed for some other use (climate-controlled storage, Maintenance offices/workshops, or something along those lines).", "latitude": 29.7304071680241, "answer_id": "9df768cd-8ab9-4a6b-a8ae-ab82b1c2c154", "longitude": -94.9756047420495, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.696285+00:00", "project_id": "X26-RB08", "question_id": "8f13babc-586d-4acc-abb7-c1a0fd13a379", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "9f0be869-7971-4898-b7e4-e78534f83bb7", "note": "Bonner Hall could use a significant amount of refresh, particularly the former Writing Center.", "latitude": 29.7313295054752, "answer_id": "9df768cd-8ab9-4a6b-a8ae-ab82b1c2c154", "longitude": -94.9759909801475, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T15:06:53.696285+00:00", "project_id": "X26-RB08", "question_id": "8f13babc-586d-4acc-abb7-c1a0fd13a379", "response_id": "c33d7546-d1d0-497b-ab55-3fb1721d213e"}'::jsonb);
