INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, E'{"id": "4687caf1-5b94-449a-b5b3-2660a86ee496", "note": "For people not familiar with the college, Rundell Hall tends to be the \\"front door\\" - the Student Success and Advising Center is in the best place, just inside this door.  Once upon a time, advising was in Moler Hall, in the center of campus - people had to figure out which building, and where it is located.", "latitude": 29.7325173518218, "answer_id": "86d60593-35d5-4d66-af2f-52cd15db408a", "longitude": -94.9781850271228, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:32:48.102925+00:00", "project_id": "X26-RB08", "question_id": "adc4763b-f468-4810-a023-79c50e99b97f", "response_id": "c8bd7e90-a20a-439f-b888-758a8923c5d6"}'::jsonb);
