INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "cd1c15e9-338e-4e0c-a66f-234c0f6e783f", "note": "The entire area south of the Arena, Science Building and Bonner, and north of the railroad tracks", "latitude": 29.730318660018, "answer_id": "ab4de489-4200-4632-8ed9-64176d1d55fa", "longitude": -94.9761250912879, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:32:48.535013+00:00", "project_id": "X26-RB08", "question_id": "b910be74-0cc8-49ca-a30b-60eeb06b04ed", "response_id": "c8bd7e90-a20a-439f-b888-758a8923c5d6"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "fa888751-735e-4ec9-8cb5-e548b073f9e6", "note": "There is no area I consider unsafe, perhaps least safe would be the area north of Market Street and west of Decker Drive.  My guess is college security personnel don''t spend as much time in that area as other areas of campus.  But again, there is no area that I consider unsafe.", "latitude": 29.7356289720855, "answer_id": "721737ca-dbe0-4c64-a2a3-8709c367ef07", "longitude": -94.9795046773367, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:32:48.668777+00:00", "project_id": "X26-RB08", "question_id": "a2f5e139-1ea9-4cc6-9862-6a12a237164c", "response_id": "c8bd7e90-a20a-439f-b888-758a8923c5d6"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "2345cce5-ebda-4e7e-aa52-f58989229387", "note": "If remaining in use, I''d say Bonner Hall and T-V 1, 2 & 3 need improvement the most.  (This assumes the other T-V buildings, physical plant, etc., at south end of campus to be demolished.)", "latitude": 29.7313155218895, "answer_id": "ee02598f-2e55-4933-a6c8-0f6bce45456a", "longitude": -94.975964169898, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:32:48.788422+00:00", "project_id": "X26-RB08", "question_id": "8f13babc-586d-4acc-abb7-c1a0fd13a379", "response_id": "c8bd7e90-a20a-439f-b888-758a8923c5d6"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "99a05ed8-7115-46c6-a551-17e2633afd56", "note": "Also, I''m not sure - it may be that facilities inside the Science Building are outdated and in need of improvement.  (Unfortunate oversight that the Science Building is not labeled on the map - this may cause people to overlook it,  in favor of buildings that are labeled)", "latitude": 29.7305142998287, "answer_id": "ee02598f-2e55-4933-a6c8-0f6bce45456a", "longitude": -94.9768546632907, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T16:32:48.788422+00:00", "project_id": "X26-RB08", "question_id": "8f13babc-586d-4acc-abb7-c1a0fd13a379", "response_id": "c8bd7e90-a20a-439f-b888-758a8923c5d6"}'::jsonb);
