INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "e569f7ae-e89d-492c-ae0f-2417c1745116", "note": "I NEVER eat on campus", "latitude": 29.7331668563063, "answer_id": "f9f350d5-498c-43f6-9691-e6bb72351dda", "longitude": -94.9802112676034, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:40.908408+00:00", "project_id": "X26-RB08", "question_id": "b91b3d5f-6b39-4885-83db-d6c548031744", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "caaf2b8c-628f-4a9b-8f9d-f273ec8b0211", "note": "Honestly, I don''t eat on campus. At all. Ever. Not even at catered events. I''ve refused to buy even the tiniest snack on campus since the Rebel Roost profits were redirected and we became a Pepsi campus.  I would rather starve.", "latitude": 29.7317846332676, "answer_id": "f9f350d5-498c-43f6-9691-e6bb72351dda", "longitude": -94.977968216337, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T17:32:40.908408+00:00", "project_id": "X26-RB08", "question_id": "b91b3d5f-6b39-4885-83db-d6c548031744", "response_id": "7b629ebb-2b3e-4de2-bc8e-a50d222f3ef3"}'::jsonb);
