INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "eda7ee7c-bae5-4f37-abda-44935ae70e05", "note": "Aesthetically speaking John Britt, Gym, Bonner Hall look like spaces from the 70''s and 80''s", "latitude": 29.7317161393613, "answer_id": "3cb93bb0-9bc6-4d1e-b196-0530f2392aa1", "longitude": -94.9779865436555, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T18:34:29.798659+00:00", "project_id": "X26-RB08", "question_id": "b910be74-0cc8-49ca-a30b-60eeb06b04ed", "response_id": "ea417ddd-5588-46e6-87b9-4142f48b9559"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "f3b2fdf3-85dc-4ee2-a70e-3bf164c77fee", "note": "The ATC building means advanced tecnology center yet most technology in that building are so severely out of date it takes more than 5 minutes for them to boot up", "latitude": 29.7313062142319, "answer_id": "3cb93bb0-9bc6-4d1e-b196-0530f2392aa1", "longitude": -94.9760768108369, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T18:34:29.798659+00:00", "project_id": "X26-RB08", "question_id": "b910be74-0cc8-49ca-a30b-60eeb06b04ed", "response_id": "ea417ddd-5588-46e6-87b9-4142f48b9559"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "5be64f1e-c0ea-4d7a-ae4b-8f52dfb2ce16", "note": "Huddle needs a complete renovation ro be torn down. I have caught so many impact kids in there ditching classes and they tell me no one goes through the building. This also means other things can be happening in that space. I would also like to add any space on campus that has elevators. For some reason we cannot get these elevators to work regularly. SOme builidngs only have 1 so if it goes down and some one can''t go down stairs that is a huge issue. Campus is not lit up enough", "latitude": 29.7321819618832, "answer_id": "3997b29e-b395-44fc-994e-905ad921dbbe", "longitude": -94.9781582062423, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T18:34:29.910919+00:00", "project_id": "X26-RB08", "question_id": "a2f5e139-1ea9-4cc6-9862-6a12a237164c", "response_id": "ea417ddd-5588-46e6-87b9-4142f48b9559"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "f12f3f7b-1434-4b42-bf4c-32a2c8060d62", "note": "Lee College is an amazing institution that looks and operates like its best days were in the 80''s and 90''s. John Britt, The Gym, Bonner Hall, Moler Hall look like they do not belong in the time.", "latitude": 29.7316229752505, "answer_id": "16517e87-e3cc-4125-8c08-ee2ec0e3c4de", "longitude": -94.9779972737011, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T18:34:30.029784+00:00", "project_id": "X26-RB08", "question_id": "8f13babc-586d-4acc-abb7-c1a0fd13a379", "response_id": "ea417ddd-5588-46e6-87b9-4142f48b9559"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "c4f80926-b474-4a67-bcce-7930f52d5f9c", "note": "TEAR DOWN THE GREENHOUSE ALREADY ITS BEEN 20 YEARS.", "latitude": 29.7313062147763, "answer_id": "16517e87-e3cc-4125-8c08-ee2ec0e3c4de", "longitude": -94.9758085911451, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T18:34:30.029784+00:00", "project_id": "X26-RB08", "question_id": "8f13babc-586d-4acc-abb7-c1a0fd13a379", "response_id": "ea417ddd-5588-46e6-87b9-4142f48b9559"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "e0ec177c-360d-4ace-801e-91ea2b8d3cd7", "note": "The student center is the singular space on campus with decent conference seating besides runell hall conference room which is a pain to reserve", "latitude": 29.7322658096097, "answer_id": "d11a1420-8ecc-431a-b8af-210d839c3f02", "longitude": -94.9761411850628, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T18:34:30.168555+00:00", "project_id": "X26-RB08", "question_id": "cd40af26-184e-4ccb-8525-1276f99c7481", "response_id": "ea417ddd-5588-46e6-87b9-4142f48b9559"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "01790294-ab11-42f4-a8fa-57e88ea77ecc", "note": "The cafe 34 is the only spot on campus. Way to expensive and students have so many options within 3 miles it is no wonder our students and staff primarily go off campus for lunch", "latitude": 29.731567076416, "answer_id": "e08be09a-f019-4649-a6ee-a5dac4a94d9c", "longitude": -94.9765917961773, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T18:34:30.315354+00:00", "project_id": "X26-RB08", "question_id": "b91b3d5f-6b39-4885-83db-d6c548031744", "response_id": "ea417ddd-5588-46e6-87b9-4142f48b9559"}'::jsonb);
INSERT INTO survey_pins SELECT * FROM jsonb_populate_record(NULL::survey_pins, '{"id": "ad56ae76-b010-40df-b0b8-1d9f077e8996", "note": "meetings are primarily held in the student center conference rooms or rundell hall conference rooms", "latitude": 29.7323310244592, "answer_id": "4d7d56ed-532a-4848-b780-601a5e9bb919", "longitude": -94.9760875408825, "sentiment": null, "survey_id": "a73aa716-b2d0-4b8b-a3e5-9123f6318008", "created_at": "2026-05-11T18:34:30.440241+00:00", "project_id": "X26-RB08", "question_id": "6d31ae57-7fb9-4853-9af3-8a88be0314ff", "response_id": "ea417ddd-5588-46e6-87b9-4142f48b9559"}'::jsonb);
